-- Helper function to set multiple highlight groups at once
local function set_hl_mutliple(groups, value)
  for _, v in pairs(groups) do
    vim.api.nvim_set_hl(0, v, value)
  end
end

-- Make selected text stand out
vim.api.nvim_set_hl(0, 'Visual', {
  bg = '{{colors.primary_container.default.hex}}',
  fg = '{{colors.on_primary_container.default.hex}}',
})

-- Clear, bright comments
set_hl_mutliple({ 'TSComment', 'Comment' }, {
  fg = '{{colors.on_surface_variant.default.hex}}',
  italic = true,
})

-- Vibrant strings
set_hl_mutliple({ 'String', 'TSString' }, {
  fg = '{{colors.tertiary.default.hex}}',
})

-------------------------------------------------------------------------------
-- Brightened Syntax Elements
-------------------------------------------------------------------------------

-- 1. Control flow (ifs, elses, returns, loops, keywords)
set_hl_mutliple({
  'Keyword',
  'Conditional',
  'Repeat',
  'Statement',
  'TSKeyword',
  'TSKeywordFunction',
  'TSConditional',
  'TSRepeat',
  '@keyword',
  '@keyword.conditional',
  '@keyword.repeat',
  '@keyword.return',
}, {
  fg = '{{colors.primary.default.hex}}',
  bold = true,
})

-- 2. Function calls & declarations
set_hl_mutliple({
  'Function',
  'TSFunction',
  'TSMethod',
  'TSFuncCall',
  'TSMethodCall',
  '@function',
  '@function.call',
  '@method',
  '@method.call',
}, {
  fg = '{{colors.tertiary.default.hex}}',
})

-- 3. Variable declarations & identifiers
set_hl_mutliple({
  'Identifier',
  'TSVariable',
  'TSVariableBuiltin',
  '@variable',
  '@variable.builtin',
  '@variable.parameter',
}, {
  fg = '{{colors.on_surface.default.hex}}',
})

-- 4. Brackets, parentheses, delimiters & operators
set_hl_mutliple({
  'Delimiter',
  'Operator',
  'TSPunctBracket',
  'TSPunctDelimiter',
  '@punctuation.bracket',
  '@punctuation.delimiter',
  '@operator',
}, {
  fg = '{{colors.on_surface.default.hex}}',
})

-------------------------------------------------------------------------------
-- Background Transparency
-------------------------------------------------------------------------------
set_hl_mutliple({ 'Normal', 'NormalNC', 'SignColumn', 'EndOfBuffer', 'NormalFloat' }, {
  bg = 'NONE',
})
